    game.zoneBanner = Math.max(0, game.zoneBanner - dt);
    game.messageTimer = Math.max(0, game.messageTimer - dt);
    flash = Math.max(0, flash - dt * 2.2);
    if (game.fade > 0) {
      game.fade = approach(game.fade, 0, dt * 1.35);
    }

