    if (game.phase === 'dead') {
      updateCamera(dt);
      updateParticles(dt);
      updateHUD(dt);
      if (boss) boss.update(dt);
      projectiles.forEach(p => p.update(dt));
      projectiles = projectiles.filter(p => !p.dead);
      return;
    }

    if (game.phase === 'victory') {
      updateParticles(dt);
      updateCamera(dt);
      return;
